const initialMinutes = [5, 8];
function totalMinutes(values) {
  return values.reduce((total, value) => total + value, 0);
}
function App() {
  const [minutes, setMinutes] = React.useState(initialMinutes);
  const total = totalMinutes(minutes);
  return <main><p role="status">Total: {total} minutes</p>
    <button onClick={() => setMinutes(current => [...current, 3])}>Add three</button>
    <button onClick={() => setMinutes([])}>Clear</button>
  </main>;
}
```
The initial total is 13. Add three gives 16; Clear gives 0. The calculation follows the current array on every render.

